import sys,json
d = json.load(sys.stdin)
# Print top-level keys and search for agent-related settings
print('Top-level keys:', list(d.keys()))
if 'providers' in d:
    for p in d['providers']:
        print(f'  Provider: {p.get(\"name\",p.get(\"id\",\"?\"))}')" 2>/dev/null || echo "file not json""}

