import sys,json,re
content = sys.stdin.read()
# Remove comments
content = re.sub(r'//.*?\\n|\\s*\\/\\*.*?\\*\\/', '', content, flags=re.DOTALL)
d = json.loads(content)
# Search for 'agent' key anywhere
